<?php namespace App\Controllers;
class MonthlyStock extends BaseController{
 public function index(){if($r=$this->mustLogin())return $r;$month=$this->request->getGet('month')?:date('Y-m');return $this->render('monthly_stock/index',['pageTitle'=>'Monthly Stock','month'=>$month,'rows'=>$this->rows($month)]);}
 private function rows($month){$db=db_connect();return $db->query("SELECT m.id,m.code,m.description,COALESCE(ms.opening_stock,0) opening_stock,ms.physical_stock_month_end,(COALESCE(ms.opening_stock,0)+COALESCE(SUM(d.receipt_qty),0)-COALESCE(SUM(d.issued_qty),0)) closing_stock,(COALESCE(ms.opening_stock,0)+COALESCE(SUM(d.receipt_qty),0)-COALESCE(SUM(d.issued_qty),0))-COALESCE(ms.physical_stock_month_end,0) difference FROM materials m LEFT JOIN monthly_stock ms ON ms.material_id=m.id AND ms.month_key=? LEFT JOIN daily_entries d ON d.material_id=m.id AND d.month_key=? GROUP BY m.id,ms.id ORDER BY m.id",[$month,$month])->getResultArray();}
 public function save(){if($r=$this->mustAdmin())return $r;$p=$this->request->getPost();$model=new \App\Models\MonthlyStockModel();$data=['material_id'=>$p['material_id'],'month_key'=>$p['month_key'],'opening_stock'=>$p['opening_stock'],'physical_stock_month_end'=>$p['physical_stock_month_end']===''?null:$p['physical_stock_month_end'],'good_stock_physical'=>$p['good_stock_physical']===''?null:$p['good_stock_physical'],'rejected_stock_physical'=>$p['rejected_stock_physical']===''?null:$p['rejected_stock_physical'],'notes'=>$p['notes']??'','created_by'=>session()->get('user')['id'],'updated_by'=>session()->get('user')['id']];$old=$model->where(['material_id'=>$p['material_id'],'month_key'=>$p['month_key']])->first();if($old)$model->update($old['id'],$data);else$model->insert($data);return redirect()->back()->with('success','Monthly stock saved.');}}
